import { Component } from 'react'
import AppFaqStyleWrapper from './component/style.js'
import { DEVICE_GIF, STEPS, CONSTANT_STRINGS } from './constants'
import IntlMessages from '../../components/utility/intlMessages'
import qs from 'qs'

class MobileAppLock extends Component {
  render () {
    let productLang = qs.parse(this.props.history.location.search.slice(1)).language_code === 'en'
    return (
      <AppFaqStyleWrapper>
        <div>
          <h3 ><b> {productLang ? CONSTANT_STRINGS.instructions_eng : CONSTANT_STRINGS.instructions_bhasa}</b></h3>
          <section>
            <br />
            <ol className='faq-points'>
              {
                STEPS.map(steps => {
                  return (
                    <li key={steps.key}>
                      <div key={steps.key} dangerouslySetInnerHTML={{ __html: productLang ? steps.step_eng : steps.step_bhasa }} />
                      <br />
                    </li>
                  )
                })}
            </ol>
          </section>
          <section>
            <h3><b> {productLang ? CONSTANT_STRINGS.example_eng : CONSTANT_STRINGS.example_bhasa} </b></h3>
            <center>
              {
                DEVICE_GIF.map(deviceGif => {
                  return (
                    <section key={deviceGif.device}>
                      <br />
                      <h4> <IntlMessages id={deviceGif.device} /></h4>
                      <img src={productLang ? deviceGif.gif_eng : deviceGif.gif_bhasa} alt='' />
                      <br />
                    </section>
                  )
                })
              }
            </center>
          </section>
        </div >
      </AppFaqStyleWrapper>
    )
  }
}

export default MobileAppLock
